import React from 'react';
import { render, screen } from '@testing-library/react';
import Heading from './Heading';

const mobileScreenSize = 360;
const tabletScreenSize = 1000;
const desktopScreenSize = 1366;

describe('Heading', () => {
  test('should render without crashing', () => {
    const { container } = render(<Heading>Heading</Heading>);
    expect(screen.getByText('Heading')).toBeInTheDocument();
    expect(container.querySelector('h1')).not.toBeNull();
  });
  test('should render as a H1 title', () => {
    const { container } = render(<Heading size="Hero">Heading</Heading>);
    expect(screen.getByText('Heading')).toBeInTheDocument();
    expect(container.querySelector('h1')).not.toBeNull();
  });
  test('should render as a H1 title', () => {
    const { container } = render(
      <Heading size="H1" foreground="true">
        Heading
      </Heading>
    );
    expect(screen.getByText('Heading')).toBeInTheDocument();
    expect(container.querySelector('h1')).not.toBeNull();
  });
  test('should render as a H2 title', () => {
    const { container } = render(<Heading size="H2">Heading</Heading>);
    expect(screen.getByText('Heading')).toBeInTheDocument();
    expect(container.querySelector('h2')).not.toBeNull();
  });
  test('should render as a H3 title', () => {
    const { container } = render(<Heading size="H3">Heading</Heading>);
    expect(screen.getByText('Heading')).toBeInTheDocument();
    expect(container.querySelector('h3')).not.toBeNull();
  });
  test('should render as a H4 title', () => {
    const { container } = render(<Heading size="H4">Heading</Heading>);
    expect(screen.getByText('Heading')).toBeInTheDocument();
    expect(container.querySelector('h4')).not.toBeNull();
  });
  test('should render as a H5 title', () => {
    const { container } = render(<Heading size="H5">Heading</Heading>);
    expect(screen.getByText('Heading')).toBeInTheDocument();
    expect(container.querySelector('h5')).not.toBeNull();
  });
  test('should render with right sizes on mobile', () => {
    global.innerWidth = mobileScreenSize;
    global.dispatchEvent(new Event('resize'));
    const { container } = render(<Heading size="H1">Heading</Heading>);
    expect(screen.getByText('Heading')).toBeInTheDocument();
    expect(container.querySelector('h1')).not.toBeNull();
  });
  test('should render with right sizes on desktop', () => {
    global.innerWidth = tabletScreenSize;
    global.dispatchEvent(new Event('resize'));
    const { container } = render(<Heading size="H1">Heading</Heading>);
    expect(screen.getByText('Heading')).toBeInTheDocument();
    expect(container.querySelector('h1')).not.toBeNull();
  });
  test('should render with right sizes on desktop', () => {
    global.innerWidth = desktopScreenSize;
    global.dispatchEvent(new Event('resize'));
    const { container } = render(<Heading size="H1">Heading</Heading>);
    expect(screen.getByText('Heading')).toBeInTheDocument();
    expect(container.querySelector('h1')).not.toBeNull();
  });
});
